  getr regs 1 = ret -> ret_ok ret -> getr regs 10 = Z_to_bv 64 k -> (0 <= k < 2 ^ 63)%Z ->
  exists regs', msteps ASEGS (mkst regs (0x11eefc : word) M rom) (mkst regs' ret M rom)
    /\ getr regs' 10 = Z_to_bv 64 k /\ keeps_cs regs regs'.
Proof.
